// انتخاب ایموجی تصادفی
func GetRandomMockEmoji() string {
	if len(MockEmojis) == 0 {
		return "😂"
	}
	return MockEmojis[rand.Intn(len(MockEmojis))]
}

// انتخاب پیام تصادفی + ایموجی تصادفی
func GetRandomEnemyMessage() string {
	if len(EnemyMessages) == 0 {
		return "سطحت به مکالمه با من نمی‌رسه، سکوت کن 😂"
	}

	message := EnemyMessages[rand.Intn(len(EnemyMessages))]
	emoji := GetRandomMockEmoji()

	return message + " " + emoji
}
